SELECT COUNT(1)
FROM checkin_record
WHERE assignment_id = #{assignmentId}
  AND user_id = #{userId}
  AND checkin_type = #{checkinType}
  AND is_deleted = 0

SELECT id, assignment_id AS assignmentId, activity_id AS activityId, position_id AS positionId, user_id AS userId, checkin_type AS checkinType, checkin_status AS checkinStatus, checkin_time AS checkinTime, longitude, latitude, qr_code AS qrCode FROM checkin_record WHERE activity_id = #{activityId}
AND user_id = #{userId}
AND is_deleted = 0 ORDER BY assignment_id ASC, checkin_time ASC
